rmC; // color\n    uniform highp usampler2D transformD; // sh\n    uniform highp sampler2D semantics;\n\n    #define SH_BANDS 3\n\n    #if SH_BANDS == 1\n        #define SH_COEFFS 3\n    #elif SH_BANDS == 2\n        #define SH_COEFFS 8\n    #elif SH_BANDS == 3\n        #define SH_COEFFS 15\n    #else\n        #define SH_COEFFS 0\n    #endif\n    \n    // const mediump vec4 discardVec = vec4(0.0, 0.0, 2.0, 1.0);\n    const float SQRT_2 = 1.414213562373095;\n    const float SQRT_2_inv = 0.7071067811865475;\n    const float COLOR_NORM = 1.0 / 255.0;\n    const float SCALE_NORM  = 1.0 / 65535.0;\n    const float ROT_NORM = 1.0 / 1023.0;\n    // const mediump vec4 effColor = vec4(1.0, 0.953, 0.2, 1.0);\n    // const mediump vec4 effColor = vec4(0.8, 0.8, 0.8, 0.8);\n    const mediump vec4 effColor = vec4(1.0, 1.0, 0.0, 1.0);\n    const float RENDER_MIN_ALPHA = 1.0f / 255.0f;\n\n    // const mat4 QUAT_TAB = mat4(\n    //     3., 0., 1., 2.,\n    //     0., 3., 1., 2.,\n    //     0., 1., 3., 2.,\n    //     0., 1., 2., 3.\n    // );\n\n    const float SH_C0 = 0.28209479177387814;\n    const float SH_C1 = 0.4886025119029199f;\n    const float SH_C2_0 = 1.0925484305920792f;\n    const float SH_C2_1 = -1.0925484305920792f;\n    const float SH_C2_2 = 0.31539156525252005f;\n    const float SH_C2_3 = -1.0925484305920792f;\n    const float SH_C2_4 = 0.5462742152960396f;\n    const float SH_C3_0 = -0.5900435899266435f;\n    const float SH_C3_1 = 2.890611442640554f;\n    const float SH_C3_2 = -0.4570457994644658f;\n    const float SH_C3_3 = 0.3731763325901154f;\n    const float SH_C3_4 = -0.4570457994644658f;\n    const float SH_C3_5 = 1.445305721320277f;\n    const float SH_C3_6 = -0.5900435899266435f;\n\n    vec3 calSH(in vec3 sh[SH_COEFFS], in vec3 dir) {\n        float x = dir.x;\n        float y = dir.y;\n        float z = dir.z;\n\n        // 1st degree\n        vec3 result = SH_C1 * (-sh[0] * y + sh[1] * z - sh[2] * x);\n\n        #if SH_BANDS > 1\n            // 2nd degree\n            float xx = x * x;\n            float yy = y * y;\n            float zz = z * z;\n            float xy = x * y;\n            float yz = y * z;\n            float xz = x * z;\n\n            result +=\n                sh[3] * (SH_C2_0 * xy) +\n                sh[4] * (SH_C2_1 * yz) +\n                sh[5] * (SH_C2_2 * (2.0 * zz - xx - yy)) +\n                sh[6] * (SH_C2_3 * xz) +\n                sh[7] * (SH_C2_4 * (xx - yy));\n        #endif\n\n        #if SH_BANDS > 2\n            // 3rd degree\n            result +=\n                sh[8]  * (SH_C3_0 * y * (3.0 * xx - yy)) +\n                sh[9]  * (SH_C3_1 * xy * z) +\n                sh[10] * (SH_C3_2 * y * (4.0 * zz - xx - yy)) +\n                sh[11] * (SH_C3_3 * z * (2.0 * zz - 3.0 * xx - 3.0 * yy)) +\n                sh[12] * (SH_C3_4 * x * (4.0 * zz - xx - yy)) +\n                sh[13] * (SH_C3_5 * z * (xx - yy)) +\n                sh[14] * (SH_C3_6 * x * (xx - 3.0 * yy));\n        #endif\n\n        return result;\n    }\n\n    mat3 calculateCov(in vec3 scale, in vec4 q)\n    {\n        // return quatToMat3\n        // vec3 rotation = vec3((uvec3(rotateEnc) >> uvec3(0, 10, 20)) & 1023u) * ROT_NORM;\n        // uint idx = (rotateEnc >> 30u) & 3u;\n        // uvec4 seq = uvec4(QUAT_TAB[idx]);\n    \n        // vec4 q;\n        // q.xyz = vec3(rotation.xyz) * SQRT_2 - SQRT_2_inv;\n        // q.w = sqrt(max(0.0, 1.0 - dot(q.xyz, q.xyz)));\n    \n        float w = q[0]; // q[seq[0]];\n        float x = q[1]; // q[seq[1]];\n        float y = q[2]; // q[seq[2]];\n        float z = q[3]; // q[seq[3]];\n        float sx = scale.x;\n        float sy = scale.y;\n        float sz = scale.z;\n\n        float x2 = x + x, y2 = y + y, z2 = z + z;\n        float xx = x * x2, yy = y * y2, zz = z * z2;\n        float xy = x * y2, xz = x * z2, yz = y * z2;\n        float wx = w * x2, wy = w * y2, wz = w * z2;\n\n        // scale * rot\n        mat3 ret = mat3(\n            sx * (1.0 - yy - zz),    sy * (xy - wz),          sz * (xz + wy),\n            sx * (xy + wz),          sy * (1.0 - xx - zz),    sz * (yz - wx),\n            sx * (xz - wy),          sy * (yz + wx),          sz * (1.0 - xx - yy)\n        );\n\n        #ifdef IS_RTK         \n            ret = ret * transpose(mat3(prj2ECEF));\n        #endif\n        ret = transpose(ret) * ret;\n    \n        return ret;\n    }\n\n    int getTargetIndex() {\n        int base = int(st.y) * int(target.x) + int(st.x);\n        int cur = int(gl_FragCoord.y) * int(target.x) + int(gl_FragCoord.x);\n        return cur - base;\n    }\n\n    #ifdef DGBCOL\n        vec3 getDgbColor(vec3 incolor, int id) {\n            if (id < 0 || id >= 8)\n                return incolor;\n\n            vec3 colors[8];\n            colors[0] = vec3(1.0, 0.0, 0.0); // 红\n            colors[1] = vec3(0.0, 1.0, 0.0); // 绿\n            colors[2] = vec3(0.0, 0.0, 1.0); // 蓝\n            colors[3] = vec3(1.0, 1.0, 0.0); // 黄\n            colors[4] = vec3(1.0, 0.0, 1.0); // 品红\n            colors[5] = vec3(0.0, 1.0, 1.0); // 青\n            colors[6] = vec3(1.0, 0.5, 0.0); // 橙\n            colors[7] = vec3(0.63, 0.13, 0.94); // 紫\n            return colors[clamp(id, 0, 7)];\n        }\n    #endif\n    "},{modelMatrix:n,modelViewMatrix:i,projectionMatrix:s,viewMatrix:r}=t;return{copySpzShaderFrag:`\n    ${e}\n\n    uvec4 transformAValue;\n\n    uint packdata8888(vec4 v) {\n        uvec4 d = uvec4(v * 255.0) << uvec4(0u, 8u, 16u, 24u);\n        return d.x | d.y | d.z | d.w;\n    }\n\n    #ifdef LCC_COMPACT\n        const float COMPACT_INV_LOG_RANGE = 255.0 / 21.0;\n        const float COMPACT_LOG_MIN = -12.0;\n        uint compactScaleComp(float s) {\n            if (s < 1e-10) return 0u;\n            return uint(clamp((log(s) - COMPACT_LOG_MIN) * COMPACT_INV_LOG_RANGE + 0.5, 1.0, 255.0));\n        }\n        uvec2 packBasic1Compact(vec3 scale, vec4 color) {\n            uint sx = compactScaleComp(scale.x);\n            uint sy = compactScaleComp(sca